-- Additive schema. Rollback retains tables; never reset user data.
CREATE TABLE IF NOT EXISTS studio_accounts (id text NOT NULL,workspace_id integer NOT NULL REFERENCES studio_workspace(id),name text NOT NULL,platform text NOT NULL DEFAULT '',status text NOT NULL DEFAULT '',payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,email text, owner_name text,PRIMARY KEY(workspace_id,id));
CREATE INDEX IF NOT EXISTS studio_accounts_active ON studio_accounts(workspace_id,created_at,id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_accounts_status ON studio_accounts(workspace_id,status) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS studio_channels (id text NOT NULL,workspace_id integer NOT NULL REFERENCES studio_workspace(id),name text NOT NULL,platform text NOT NULL DEFAULT '',status text NOT NULL DEFAULT '',payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,url text, owner_name text, followers bigint CHECK(followers>=0),PRIMARY KEY(workspace_id,id));
CREATE INDEX IF NOT EXISTS studio_channels_active ON studio_channels(workspace_id,created_at,id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_channels_status ON studio_channels(workspace_id,status) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS studio_campaigns (id text NOT NULL,workspace_id integer NOT NULL REFERENCES studio_workspace(id),name text NOT NULL,platform text NOT NULL DEFAULT '',status text NOT NULL DEFAULT '',payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,owner_name text, starts_on date, ends_on date, budget numeric(18,2) CHECK(budget>=0), spent numeric(18,2) CHECK(spent>=0),PRIMARY KEY(workspace_id,id));
CREATE INDEX IF NOT EXISTS studio_campaigns_active ON studio_campaigns(workspace_id,created_at,id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_campaigns_status ON studio_campaigns(workspace_id,status) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS studio_posts (id text NOT NULL,workspace_id integer NOT NULL REFERENCES studio_workspace(id),name text NOT NULL,platform text NOT NULL DEFAULT '',status text NOT NULL DEFAULT '',payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,content text, planned_at timestamptz, campaign_id text, FOREIGN KEY(workspace_id,campaign_id) REFERENCES studio_campaigns(workspace_id,id),PRIMARY KEY(workspace_id,id));
CREATE INDEX IF NOT EXISTS studio_posts_active ON studio_posts(workspace_id,created_at,id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_posts_status ON studio_posts(workspace_id,status) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS studio_ads (id text NOT NULL,workspace_id integer NOT NULL REFERENCES studio_workspace(id),name text NOT NULL,platform text NOT NULL DEFAULT '',status text NOT NULL DEFAULT '',payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,campaign_id text, budget numeric(18,2) CHECK(budget>=0), spent numeric(18,2) CHECK(spent>=0), clicks bigint CHECK(clicks>=0), FOREIGN KEY(workspace_id,campaign_id) REFERENCES studio_campaigns(workspace_id,id),PRIMARY KEY(workspace_id,id));
CREATE INDEX IF NOT EXISTS studio_ads_active ON studio_ads(workspace_id,created_at,id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_ads_status ON studio_ads(workspace_id,status) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS studio_customers (id text NOT NULL,workspace_id integer NOT NULL REFERENCES studio_workspace(id),name text NOT NULL,platform text NOT NULL DEFAULT '',status text NOT NULL DEFAULT '',payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,email text, source text, visits bigint CHECK(visits>=0),PRIMARY KEY(workspace_id,id));
CREATE INDEX IF NOT EXISTS studio_customers_active ON studio_customers(workspace_id,created_at,id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_customers_status ON studio_customers(workspace_id,status) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS studio_keywords (id text NOT NULL,workspace_id integer NOT NULL REFERENCES studio_workspace(id),name text NOT NULL,platform text NOT NULL DEFAULT '',status text NOT NULL DEFAULT '',payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,url text, rank integer CHECK(rank>=0), previous_rank integer CHECK(previous_rank>=0), search_volume bigint CHECK(search_volume>=0),PRIMARY KEY(workspace_id,id));
CREATE INDEX IF NOT EXISTS studio_keywords_active ON studio_keywords(workspace_id,created_at,id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_keywords_status ON studio_keywords(workspace_id,status) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS studio_competitors (id text NOT NULL,workspace_id integer NOT NULL REFERENCES studio_workspace(id),name text NOT NULL,platform text NOT NULL DEFAULT '',status text NOT NULL DEFAULT '',payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,url text, traffic bigint CHECK(traffic>=0), keyword_count bigint CHECK(keyword_count>=0), score numeric(10,2),PRIMARY KEY(workspace_id,id));
CREATE INDEX IF NOT EXISTS studio_competitors_active ON studio_competitors(workspace_id,created_at,id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_competitors_status ON studio_competitors(workspace_id,status) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS studio_conversations (id text NOT NULL,workspace_id integer NOT NULL REFERENCES studio_workspace(id),name text NOT NULL,platform text NOT NULL DEFAULT '',status text NOT NULL DEFAULT '',payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,customer_id text, FOREIGN KEY(workspace_id,customer_id) REFERENCES studio_customers(workspace_id,id),PRIMARY KEY(workspace_id,id));
CREATE INDEX IF NOT EXISTS studio_conversations_active ON studio_conversations(workspace_id,created_at,id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_conversations_status ON studio_conversations(workspace_id,status) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS studio_rank_checks (id text NOT NULL,workspace_id integer NOT NULL REFERENCES studio_workspace(id),name text NOT NULL,platform text NOT NULL DEFAULT '',status text NOT NULL DEFAULT '',payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,keyword_id text, url text, region text, rank integer CHECK(rank>=0), FOREIGN KEY(workspace_id,keyword_id) REFERENCES studio_keywords(workspace_id,id),PRIMARY KEY(workspace_id,id));
CREATE INDEX IF NOT EXISTS studio_rank_checks_active ON studio_rank_checks(workspace_id,created_at,id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_rank_checks_status ON studio_rank_checks(workspace_id,status) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS studio_workflows (id text NOT NULL,workspace_id integer NOT NULL REFERENCES studio_workspace(id),name text NOT NULL,platform text NOT NULL DEFAULT '',status text NOT NULL DEFAULT '',payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,PRIMARY KEY(workspace_id,id));
CREATE INDEX IF NOT EXISTS studio_workflows_active ON studio_workflows(workspace_id,created_at,id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_workflows_status ON studio_workflows(workspace_id,status) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS studio_workflow_runs (id text NOT NULL,workspace_id integer NOT NULL REFERENCES studio_workspace(id),name text NOT NULL,platform text NOT NULL DEFAULT '',status text NOT NULL DEFAULT '',payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,PRIMARY KEY(workspace_id,id));
CREATE INDEX IF NOT EXISTS studio_workflow_runs_active ON studio_workflow_runs(workspace_id,created_at,id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_workflow_runs_status ON studio_workflow_runs(workspace_id,status) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS studio_metrics (id text NOT NULL,workspace_id integer NOT NULL REFERENCES studio_workspace(id),name text NOT NULL,platform text NOT NULL DEFAULT '',status text NOT NULL DEFAULT '',payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,PRIMARY KEY(workspace_id,id));
