CREATE INDEX IF NOT EXISTS studio_traffic_events_active ON studio_traffic_events(workspace_id,created_at,id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_traffic_events_status ON studio_traffic_events(workspace_id,status) WHERE deleted_at IS NULL;
