CREATE TABLE IF NOT EXISTS studio_media (id text NOT NULL,workspace_id integer NOT NULL REFERENCES studio_workspace(id),name text NOT NULL,platform text NOT NULL DEFAULT '',status text NOT NULL DEFAULT '',payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,PRIMARY KEY(workspace_id,id));
