CREATE INDEX IF NOT EXISTS studio_notifications_active ON studio_notifications(workspace_id,created_at,id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_notifications_status ON studio_notifications(workspace_id,status) WHERE deleted_at IS NULL;
