CREATE INDEX IF NOT EXISTS studio_settings_active ON studio_settings(workspace_id,created_at,id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_settings_status ON studio_settings(workspace_id,status) WHERE deleted_at IS NULL;
