CREATE INDEX IF NOT EXISTS studio_tags_active ON studio_tags(workspace_id,created_at,id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_tags_status ON studio_tags(workspace_id,status) WHERE deleted_at IS NULL;
