CREATE INDEX IF NOT EXISTS studio_approvals_active ON studio_approvals(workspace_id,created_at,id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_approvals_status ON studio_approvals(workspace_id,status) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS studio_social_accounts (id text NOT NULL,workspace_id integer NOT NULL REFERENCES studio_workspace(id),name text NOT NULL,platform text NOT NULL DEFAULT '',status text NOT NULL DEFAULT '',payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,PRIMARY KEY(workspace_id,id));
CREATE INDEX IF NOT EXISTS studio_social_accounts_active ON studio_social_accounts(workspace_id,created_at,id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_social_accounts_status ON studio_social_accounts(workspace_id,status) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS studio_posts_campaign ON studio_posts(workspace_id,campaign_id);
CREATE INDEX IF NOT EXISTS studio_ads_campaign ON studio_ads(workspace_id,campaign_id);
CREATE INDEX IF NOT EXISTS studio_conversations_customer ON studio_conversations(workspace_id,customer_id);
CREATE INDEX IF NOT EXISTS studio_rank_keyword ON studio_rank_checks(workspace_id,keyword_id);
CREATE TABLE IF NOT EXISTS studio_post_items(workspace_id integer NOT NULL,post_id text NOT NULL,item_index integer NOT NULL,kind text NOT NULL CHECK(kind IN ('post','reply')),content text NOT NULL,delay_minutes integer NOT NULL DEFAULT 0 CHECK(delay_minutes>=0),image_data text,PRIMARY KEY(workspace_id,post_id,item_index),FOREIGN KEY(workspace_id,post_id) REFERENCES studio_posts(workspace_id,id));
CREATE TABLE IF NOT EXISTS studio_messages(workspace_id integer NOT NULL,conversation_id text NOT NULL,message_index integer NOT NULL,sender text NOT NULL,content text NOT NULL,sent_label text,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,conversation_id,message_index),FOREIGN KEY(workspace_id,conversation_id) REFERENCES studio_conversations(workspace_id,id));
CREATE TABLE IF NOT EXISTS studio_delivery_history(id bigserial PRIMARY KEY,delivery_id uuid NOT NULL REFERENCES publishing_deliveries(id),status text NOT NULL,provider_post_id text,error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS studio_delivery_history_delivery ON studio_delivery_history(delivery_id,id);
CREATE OR REPLACE FUNCTION studio_track_delivery() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='INSERT' OR OLD.status IS DISTINCT FROM NEW.status THEN INSERT INTO studio_delivery_history(delivery_id,status,provider_post_id,error) VALUES(NEW.id,NEW.status,NEW.provider_post_id,NEW.error); END IF;RETURN NEW;END; $$;
DROP TRIGGER IF EXISTS studio_delivery_history_trigger ON publishing_deliveries;
CREATE TRIGGER studio_delivery_history_trigger AFTER INSERT OR UPDATE ON publishing_deliveries FOR EACH ROW EXECUTE FUNCTION studio_track_delivery();
